.btn-primary{background:var(--blue);border-color:var(--blue)}.btn{border-radius:8px;font-size:13px;padding:8px 13px}.form-control,.form-select{font-size:13px;border-color:#dfe4ed;border-radius:8px;padding:9px 11px}.form-label{font-size:12px;font-weight:650;color:#596579}
