.login-wrap{min-height:100vh;display:grid;place-items:center;background:linear-gradient(135deg,#14233b,#315efb)}.login-card{width:min(420px,92vw);background:white;border-radius:18px;padding:32px;box-shadow:0 20px 70px #0c183866}
