 </nav>
 <div class="position-absolute bottom-0 start-0 p-3 w-100"><div class="small text-white-50 mb-2" id="userLabel"></div><button class="btn btn-outline-light btn-sm w-100" onclick="logout()"><i class="bi bi-box-arrow-left me-1"></i>Logout</button></div>
</aside>
<main class="main">
 <div class="topbar"><div><h1 class="page-title" id="pageTitle">Dashboard</h1><div class="sub" id="pageSub">Business overview and today's activity</div></div><div class="text-end"><div class="fw-semibold small" id="today"></div><div class="text-secondary small">Omkar Trading</div></div></div>
 <div id="content"></div>
</main>
</div>
<div class="position-fixed top-0 end-0 p-3" style="z-index:1080"><div id="toast" class="toast align-items-center text-bg-dark border-0"><div class="d-flex"><div class="toast-body" id="toastText"></div><button class="btn-close btn-close-white me-2 m-auto" data-bs-dismiss="toast"></button></div></div></div>
<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script>
<script>
const $=s=>document.querySelector(s), money=n=>'₹'+Number(n||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
let currentUser=null, products=[], categories=[], page='dashboard';
const titles={dashboard:['Dashboard',"Business overview and today's activity"],inventory:['Inventory','Manage raw materials and finished furniture'],purchase:['Purchase Entry','Record purchases and increase available stock'],sales:['Sales & Invoice','Create customer invoices and deduct stock'],quotation:['Quotations','Prepare estimates for customers'],parties:['Customers & Suppliers','Manage business contacts'],manufacturing:['Manufacturing','Consume raw materials and add finished furniture stock'],movements:['Stock Movements','Audit trail of inventory changes'],reports:['Reports','Monthly sales and purchase summary']};
async function api(action,data=null,method='POST'){
 const opts=method==='GET'?{method:'GET'}:{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(data??{})};
 const r=await fetch('API.php?action='+encodeURIComponent(action)+(method==='GET'&&data?'&'+new URLSearchParams(data):''),opts);
 const j=await r.json(); if(!r.ok||!j.success) throw new Error(j.message||'Request failed'); return j.data;
}
function toast(msg){$('#toastText').textContent=msg;bootstrap.Toast.getOrCreateInstance($('#toast')).show()}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function setPage(p){page=p;document.querySelectorAll('.nav-link').forEach(a=>a.classList.toggle('active',a.dataset.page===p));$('#pageTitle').textContent=titles[p][0];$('#pageSub').textContent=titles[p][1];render()}
async function init(){try{currentUser=await api('me',null,'GET');if(!currentUser){showLogin();return}showApp()}catch(e){showLogin()}}
function showLogin(){$('#loginScreen').classList.remove('d-none');$('#app').classList.add('d-none')}
function showApp(){$('#loginScreen').classList.add('d-none');$('#app').classList.remove('d-none');$('#userLabel').textContent=(currentUser.name||'User')+' · '+(currentUser.role||'');$('#today').textContent=new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'});render()}
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{currentUser=await api('login',Object.fromEntries(f));showApp()}catch(err){$('#loginError').textContent=err.message}});
async function logout(){await api('logout',{});currentUser=null;showLogin()}
document.querySelectorAll('.nav-link').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();setPage(a.dataset.page)}));
async function loadBase(){[products,categories]=await Promise.all([api('products',null,'GET'),api('categories',null,'GET')])}
async function render(){try{if(['inventory','purchase','sales','quotation'].includes(page))await loadBase();const fn={dashboard:dashboard,inventory:inventory,purchase:()=>documentForm('purchase'),sales:()=>documentForm('sale'),quotation:()=>documentForm('quotation'),manufacturing:manufacturing,parties:parties,movements:movements,reports:reports}[page];await fn()}catch(e){$('#content').innerHTML=`<div class="alert alert-danger">${esc(e.message)}</div>`}}
function stat(label,value,icon,color){return `<div class="col-6 col-xl-4"><div class="stat-card"><div class="d-flex justify-content-between"><div class="stat-label mt-0">${label}</div><div class="stat-icon" style="background:${color}"><i class="bi ${icon}"></i></div></div><div class="stat-value">${value}</div></div></div>`}
async function dashboard(){const d=await api('dashboard',null,'GET'),s=d.stats;$('#content').innerHTML=`
<div class="row g-3 mb-4">${stat('Active Products',s.products,'bi-box-seam','#eaf0ff')}${stat('Inventory Value',money(s.stock_value),'bi-currency-rupee','#e8f8ef')}${stat('This Month Purchase',money(s.purchase_month),'bi-cart-plus','#fff4e5')}${stat('This Month Sales',money(s.sales_month),'bi-graph-up-arrow','#f1eaff')}${stat('Low Stock Items',s.low_stock,'bi-exclamation-triangle','#fff0ef')}${stat('Pending Quotations',s.quotes_pending,'bi-file-earmark-text','#e9f8fa')}</div>
<div class="row g-3"><div class="col-lg-7"><div class="panel"><div class="panel-title">Recent Transactions</div>${d.recent.length?`<div class="table-responsive"><table class="table"><thead><tr><th>Type</th><th>Document</th><th>Party</th><th>Date</th><th class="text-end">Amount</th></tr></thead><tbody>${d.recent.map(x=>`<tr><td><span class="badge-soft">${x.type}</span></td><td>${esc(x.doc_no)}</td><td>${esc(x.party)}</td><td>${esc(x.doc_date)}</td><td class="text-end fw-semibold">${money(x.grand_total)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No transactions recorded yet.</div>'}</div></div>
<div class="col-lg-5"><div class="panel"><div class="panel-title">Low Stock Alerts</div>${d.low_stock.length?d.low_stock.map(x=>`<div class="d-flex justify-content-between border-bottom py-2"><div><div class="fw-semibold small">${esc(x.name)}</div><div class="text-secondary small">${esc(x.sku)}</div></div><div class="text-end"><div class="text-danger fw-bold">${x.stock_qty} ${esc(x.unit)}</div><small class="text-secondary">Reorder at ${x.reorder_level}</small></div></div>`).join(''):'<div class="empty">No low stock items.</div>'}</div></div></div>`}
async function inventory(){const rows=products;$('#content').innerHTML=`<div class="panel"><div class="d-flex justify-content-between align-items-center mb-3"><div class="panel-title mb-0">Product Catalogue</div><button class="btn btn-primary" onclick="productModal()"><i class="bi bi-plus-lg me-1"></i>Add Product</button></div><div class="table-responsive"><table class="table"><thead><tr><th>SKU</th><th>Product</th><th>Category</th><th>Unit</th><th>Purchase Rate</th><th>Selling Rate</th><th>Available</th><th>Stock Status</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.sku)}</td><td class="fw-semibold">${esc(p.name)}</td><td>${esc(p.category_name||'-')}</td><td>${esc(p.unit)}</td><td>${money(p.purchase_rate)}</td><td>${money(p.selling_rate)}</td><td class="fw-bold">${p.stock_qty} ${esc(p.unit)}</td><td>${Number(p.stock_qty)<=Number(p.reorder_level)?'<span class="badge text-bg-danger">Low stock</span>':'<span class="badge text-bg-success">In stock</span>'}</td></tr>`).join('')}</tbody></table></div></div>`}
function productModal(){const html=`<div class="modal fade" id="productModal"><div class="modal-dialog"><form class="modal-content" id="productForm"><div class="modal-header"><h5 class="modal-title">Add Inventory Product</h5><button class="btn-close" data-bs-dismiss="modal" type="button"></button></div><div class="modal-body row g-3"><div class="col-6"><label class="form-label">SKU / Code</label><input class="form-control" name="sku" placeholder="Auto if blank"></div><div class="col-6"><label class="form-label">Product Name *</label><input class="form-control" name="name" required></div><div class="col-6"><label class="form-label">Category</label><select class="form-select" name="category_id">${categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="col-6"><label class="form-label">Unit</label><select class="form-select" name="unit">${['Piece','KG','Meter','Feet','Sheet','Roll','Set','Litre'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="col-4"><label class="form-label">Purchase Rate</label><input class="form-control" name="purchase_rate" type="number" min="0" step=".01" value="0"></div><div class="col-4"><label class="form-label">Selling Rate</label><input class="form-control" name="selling_rate" type="number" min="0" step=".01" value="0"></div><div class="col-4"><label class="form-label">Reorder Level</label><input class="form-control" name="reorder_level" type="number" min="0" step=".001" value="0"></div><div class="small text-secondary">Opening stock should be entered through a purchase or opening-stock adjustment workflow to preserve the audit trail.</div></div><div class="modal-footer"><button class="btn btn-light" data-bs-dismiss="modal" type="button">Cancel</button><button class="btn btn-primary">Save Product</button></div></form></div></div>`;document.body.insertAdjacentHTML('beforeend',html);const el=$('#productModal');bootstrap.Modal.getOrCreateInstance(el).show();$('#productForm').onsubmit=async e=>{e.preventDefault();try{await api('save_product',Object.fromEntries(new FormData(e.target)));bootstrap.Modal.getInstance(el).hide();el.remove();toast('Product added');render()}catch(err){toast(err.message)}};el.addEventListener('hidden.bs.modal',()=>el.remove())}
async function documentForm(type){const isPurchase=type==='purchase',isQuote=type==='quotation';const label=isPurchase?'Supplier': 'Customer';const itemTitle=isQuote?'Description':'Product';$('#content').innerHTML=`<div class="panel"><div class="d-flex justify-content-between align-items-center mb-3"><div class="panel-title mb-0">${isPurchase?'New Purchase Entry':isQuote?'New Customer Quotation':'New Sales Invoice'}</div><span class="badge-soft">${isPurchase?'Stock In':isQuote?'Estimate only':'Stock Out'}</span></div>
<form id="docForm"><div class="row g-3 mb-3"><div class="col-md-4"><label class="form-label">${label} Name *</label><input class="form-control" name="${isPurchase?'supplier_name':'customer_name'}" required placeholder="${label} name"></div><div class="col-md-3"><label class="form-label">Mobile</label><input class="form-control" name="${isPurchase?'supplier_phone':'customer_phone'}"></div><div class="col-md-3"><label class="form-label">Date</label><input class="form-control" type="date" name="date" value="${new Date().toISOString().slice(0,10)}"></div>${isQuote?'<div class="col-md-2"><label class="form-label">Valid Until</label><input class="form-control" type="date" name="valid_until" value="'+new Date(Date.now()+15*86400000).toISOString().slice(0,10)+'"></div>':''}</div>
<div class="table-responsive"><table class="table" id="itemsTable"><thead><tr><th>${itemTitle}</th><th style="width:120px">Quantity</th><th style="width:150px">Rate (₹)</th><th style="width:140px" class="text-end">Amount</th><th></th></tr></thead><tbody id="itemRows"></tbody></table></div><button type="button" class="btn btn-outline-primary btn-sm mb-3" onclick="addItem('${type}')"><i class="bi bi-plus-lg me-1"></i>Add line item</button>
<div class="row g-3"><div class="col-md-6"><label class="form-label">Notes</label><textarea class="form-control" name="notes" rows="3" placeholder="Optional notes"></textarea></div><div class="col-md-6"><div class="row g-2">${!isPurchase?`<div class="col-6"><label class="form-label">Labour Charges</label><input class="form-control extra" name="labour" type="number" min="0" value="0"></div><div class="col-6"><label class="form-label">Other Charges / Transport</label><input class="form-control extra" name="other" type="number" min="0" value="0"></div>`:''}<div class="col-6"><label class="form-label">Tax Mode</label><select class="form-select extra" name="tax_mode"><option value="Non-GST">Non-GST</option><option value="GST">GST</option></select></div><div class="col-6"><label class="form-label">GST Rate (%)</label><select class="form-select extra" name="tax_rate"><option value="5">5%</option><option value="12">12%</option><option value="18" selected>18%</option><option value="28">28%</option></select></div><div class="col-6"><label class="form-label">Discount (₹)</label><input class="form-control extra" name="discount" type="number" min="0" value="0"></div>${type==='sale'?'<div class="col-6"><label class="form-label">Payment Status</label><select class="form-select" name="payment_status"><option>Unpaid</option><option>Paid</option><option>Partial</option></select></div>':''}<div class="col-12 text-end"><div class="text-secondary small">Estimated Grand Total</div><div class="fs-3 fw-bold" id="grandTotal">₹0.00</div></div></div></div></div><div class="d-flex justify-content-end gap-2 mt-4"><button type="reset" class="btn btn-light">Reset</button><button class="btn btn-primary">${isPurchase?'Save Purchase':isQuote?'Create Quotation':'Save Sale & Generate Invoice'}</button></div></form></div>
<div class="panel mt-3"><div class="small text-secondary"><b>Stock behaviour:</b> Purchase increases stock; Sales decreases stock; Quotations do not change stock. A sale cannot be saved if available stock is insufficient.</div></div>`;
addItem(type);$('#docForm').addEventListener('input',calcTotal);$('#docForm').onsubmit=e=>saveDocument(e,type)}
function addItem(type){const isQuote=type==='quotation';const tr=document.createElement('tr');tr.className='item-row';tr.innerHTML=`<td>${isQuote?'<input class="form-control desc" placeholder="e.g. Custom 3-seater sofa" required>':`<select class="form-select product-select" required><option value="">Select product</option>${products.map(p=>`<option value="${p.id}" data-rate="${type==='purchase'?p.purchase_rate:p.selling_rate}" data-unit="${esc(p.unit)}">${esc(p.name)} (Stock: ${p.stock_qty} ${esc(p.unit)})</option>`).join('')}</select>`}</td><td><input class="form-control qty" type="number" min=".001" step=".001" value="1" required></td><td><input class="form-control rate" type="number" min="0" step=".01" value="0" required></td><td class="text-end fw-semibold line-total">₹0.00</td><td><button type="button" class="btn btn-sm btn-light text-danger" onclick="this.closest('tr').remove();calcTotal()"><i class="bi bi-trash"></i></button></td>`;$('#itemRows').appendChild(tr);const sel=tr.querySelector('.product-select');if(sel)sel.onchange=()=>{const o=sel.selectedOptions[0];tr.querySelector('.rate').value=o.dataset.rate||0;calcTotal()};tr.querySelectorAll('input').forEach(i=>i.addEventListener('input',calcTotal));calcTotal()}
function calcTotal(){let sum=0;document.querySelectorAll('.item-row').forEach(r=>{const q=Number(r.querySelector('.qty').value||0),rate=Number(r.querySelector('.rate').value||0),v=q*rate;sum+=v;r.querySelector('.line-total').textContent=money(v)});const f=$('#docForm');if(!f)return;const val=n=>Number(f.elements[n]?.value||0);const taxable=Math.max(0,sum+val('labour')+val('other')-val('discount'));const tax=f.elements.tax_mode?.value==='GST'?taxable*val('tax_rate')/100:0;const total=taxable+tax;$('#grandTotal').textContent=money(Math.max(0,total))}
async function saveDocument(e,type){e.preventDefault();const f=e.target,fd=Object.fromEntries(new FormData(f));const items=[...document.querySelectorAll('.item-row')].map(r=>({product_id:r.querySelector('.product-select')?.value,description:r.querySelector('.desc')?.value,qty:r.querySelector('.qty').value,rate:r.querySelector('.rate').value,unit:r.querySelector('.product-select')?.selectedOptions[0]?.dataset.unit||'Piece'}));if(items.some(i=>!i.product_id&&!i.description)){toast('Select or describe every line item.');return}const printWindow=type==='purchase'?null:window.open('','_blank');try{const result=await api(type, {...fd,items});toast(`${result.document_no} saved successfully`);render();if(type!=='purchase'){if(printWindow)showDocumentPrint(type,result,fd,items,printWindow);else toast('Saved. Allow pop-ups to print or save the PDF.')}}catch(err){if(printWindow)printWindow.close();toast(err.message)}}
function showDocumentPrint(type,result,form,items,w){const title=type==='sale'?'TAX / SALES INVOICE':'QUOTATION';const party=form.customer_name||'Customer';const sub=items.reduce((a,x)=>a+Number(x.qty)*Number(x.rate),0);const labour=Number(form.labour||0),other=Number(form.other||0),discount=Number(form.discount||0),taxable=Math.max(0,sub+labour+other-discount),tax=form.tax_mode==='GST'?taxable*Number(form.tax_rate||0)/100:0,total=taxable+tax;w.document.write(`<html><head><title>${title} ${result.document_no}</title><style>body{font:14px Arial;padding:35px;color:#222}h1{margin:0}small{color:#666}.head{display:flex;justify-content:space-between;border-bottom:2px solid #222;padding-bottom:18px}.meta{margin:25px 0;display:flex;justify-content:space-between}table{width:100%;border-collapse:collapse;margin-top:25px}th,td{border:1px solid #ddd;padding:11px;text-align:left}th{background:#f3f4f6}.right{text-align:right}.total{margin:20px 0 0 auto;width:280px}.total div{display:flex;justify-content:space-between;padding:5px}.grand{font-size:19px;font-weight:bold;border-top:2px solid #222;margin-top:7px;padding-top:10px}.foot{margin-top:70px;text-align:center;color:#666}@media print{button{display:none}}</style></head><body><div class="head"><div><h1>OMKAR TRADING</h1><small>Furniture • Raw Material • Custom Manufacturing</small></div><div class="right"><h2>${title}</h2><b>${result.document_no}</b><br>${form.date||''}</div></div><div class="meta"><div><b>Bill To</b><br>${esc(party)}<br>${esc(form.customer_phone||form.supplier_phone||'')}<br>${esc(form.customer_address||'')}</div><div class="right"><b>${type==='sale'?'Invoice':'Quotation'} Details</b><br>${type==='quotation'?'Valid until: '+esc(form.valid_until||''):'Payment: '+esc(form.payment_status||'')}</div></div><table><thead><tr><th>#</th><th>Description</th><th>Qty</th><th>Rate</th><th class="right">Amount</th></tr></thead><tbody>${items.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.description||products.find(p=>p.id==x.product_id)?.name||'Item')}</td><td>${x.qty} ${esc(x.unit)}</td><td>₹${Number(x.rate).toFixed(2)}</td><td class="right">₹${(Number(x.qty)*Number(x.rate)).toFixed(2)}</td></tr>`).join('')}</tbody></table><div class="total"><div><span>Subtotal</span><b>${money(sub)}</b></div><div><span>Labour</span><b>${money(labour)}</b></div><div><span>Other charges</span><b>${money(other)}</b></div><div><span>${form.tax_mode==='GST'?'GST ('+Number(form.tax_rate||0)+'%)':'Tax (Non-GST)'}</span><b>${money(tax)}</b></div><div><span>Discount</span><b>- ${money(discount)}</b></div><div class="grand"><span>Grand Total</span><span>${money(total)}</span></div></div><div class="foot">Thank you for your business.<br><small>Computer-generated document • Please verify GST and business details before issuing.</small></div><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
async function manufacturing(){
 const raw=products.filter(p=>Number(p.category_id)!==6), finished=products.filter(p=>Number(p.category_id)===6);
 $('#content').innerHTML=`<div class="panel"><div class="panel-title">Create Production Batch</div><form id="mfgForm"><div class="row g-3 mb-3"><div class="col-md-5"><label class="form-label">Finished Product *</label><select class="form-select" name="finished_product_id" required><option value="">Select finished furniture</option>${finished.map(p=>`<option value="${p.id}">${esc(p.name)} (Current: ${p.stock_qty} ${esc(p.unit)})</option>`).join('')}</select></div><div class="col-md-3"><label class="form-label">Output Quantity *</label><input class="form-control" name="output_quantity" type="number" min=".001" step=".001" value="1" required></div><div class="col-md-4"><label class="form-label">Production Date</label><input class="form-control" name="date" type="date" value="${new Date().toISOString().slice(0,10)}"></div></div><div class="panel-title mt-4">Raw Materials Consumed</div><div class="table-responsive"><table class="table"><thead><tr><th>Raw Material</th><th>Quantity Used</th><th>Unit Cost (₹)</th><th class="text-end">Cost</th><th></th></tr></thead><tbody id="mfgRows"></tbody></table></div><button type="button" class="btn btn-outline-primary btn-sm" onclick="addMfgItem()"><i class="bi bi-plus-lg me-1"></i>Add raw material</button><div class="row g-3 mt-3"><div class="col-md-3"><label class="form-label">Labour Cost (₹)</label><input class="form-control mfg-extra" name="labour_cost" type="number" min="0" value="0"></div><div class="col-md-3"><label class="form-label">Other Cost (₹)</label><input class="form-control mfg-extra" name="other_cost" type="number" min="0" value="0"></div><div class="col-md-6"><label class="form-label">Notes</label><input class="form-control" name="notes" placeholder="Batch notes"></div></div><div class="text-end mt-3"><div class="text-secondary small">Total Production Cost</div><div class="fs-3 fw-bold" id="mfgTotal">₹0.00</div><button class="btn btn-primary mt-2">Complete Production</button></div></form></div><div class="panel mt-3"><div class="small text-secondary"><b>Manufacturing logic:</b> Raw material stock is deducted; finished goods stock is increased. Labour and other costs are included in the finished unit's estimated cost. This demo uses manual material quantities; recipe/BOM templates can be added in the next iteration.</div></div>`;
 addMfgItem();$('#mfgForm').addEventListener('input',calcMfg);$('#mfgForm').onsubmit=saveManufacturing;
}
function addMfgItem(){const raw=products.filter(p=>Number(p.category_id)!==6);const tr=document.createElement('tr');tr.className='mfg-row';tr.innerHTML=`<td><select class="form-select mfg-product" required><option value="">Select raw material</option>${raw.map(p=>`<option value="${p.id}" data-rate="${p.purchase_rate}" data-unit="${esc(p.unit)}">${esc(p.name)} (${p.stock_qty} ${esc(p.unit)} available)</option>`).join('')}</select></td><td><input class="form-control mfg-qty" type="number" min=".001" step=".001" value="1" required></td><td><input class="form-control mfg-rate" type="number" min="0" step=".01" value="0" required></td><td class="text-end fw-semibold mfg-line">₹0.00</td><td><button type="button" class="btn btn-sm btn-light text-danger" onclick="this.closest('tr').remove();calcMfg()"><i class="bi bi-trash"></i></button></td>`;$('#mfgRows').appendChild(tr);tr.querySelector('.mfg-product').onchange=e=>{tr.querySelector('.mfg-rate').value=e.target.selectedOptions[0].dataset.rate||0;calcMfg()};tr.querySelectorAll('input').forEach(x=>x.addEventListener('input',calcMfg));calcMfg()}
function calcMfg(){let sum=0;document.querySelectorAll('.mfg-row').forEach(r=>{const v=Number(r.querySelector('.mfg-qty').value||0)*Number(r.querySelector('.mfg-rate').value||0);sum+=v;r.querySelector('.mfg-line').textContent=money(v)});const f=$('#mfgForm');if(f)$('#mfgTotal').textContent=money(sum+Number(f.elements.labour_cost.value||0)+Number(f.elements.other_cost.value||0))}
async function saveManufacturing(e){e.preventDefault();const f=e.target,fd=Object.fromEntries(new FormData(f));const items=[...document.querySelectorAll('.mfg-row')].map(r=>({product_id:r.querySelector('.mfg-product').value,qty:r.querySelector('.mfg-qty').value,rate:r.querySelector('.mfg-rate').value}));if(items.some(x=>!x.product_id)){toast('Select every raw material.');return}try{const result=await api('manufacture',{...fd,items});toast(`${result.document_no} completed · Unit cost ${money(result.unit_cost)}`);render()}catch(err){toast(err.message)}}
async function parties(){const [c,s]=await Promise.all([api('parties',{type:'Customer'},'GET'),api('parties',{type:'Supplier'},'GET')]);$('#content').innerHTML=`<div class="d-flex justify-content-end mb-3"><button class="btn btn-primary" onclick="partyModal()"><i class="bi bi-plus-lg me-1"></i>Add Contact</button></div><div class="row g-3"><div class="col-lg-6"><div class="panel"><div class="panel-title">Customers (${c.length})</div>${partyTable(c)}</div></div><div class="col-lg-6"><div class="panel"><div class="panel-title">Suppliers (${s.length})</div>${partyTable(s)}</div></div></div>`}
function partyTable(rows){return rows.length?`<div class="table-responsive"><table class="table"><thead><tr><th>Name</th><th>Phone</th><th>Address</th></tr></thead><tbody>${rows.map(p=>`<tr><td class="fw-semibold">${esc(p.name)}</td><td>${esc(p.phone)}</td><td>${esc(p.address)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No contacts yet.</div>'}
function partyModal(){const html=`<div class="modal fade" id="partyModal"><div class="modal-dialog"><form class="modal-content" id="partyForm"><div class="modal-header"><h5>Add Customer / Supplier</h5><button class="btn-close" data-bs-dismiss="modal" type="button"></button></div><div class="modal-body"><label class="form-label">Contact Type</label><select class="form-select mb-3" name="party_type"><option>Customer</option><option>Supplier</option></select><label class="form-label">Name *</label><input class="form-control mb-3" name="name" required><label class="form-label">Phone</label><input class="form-control mb-3" name="phone"><label class="form-label">Email</label><input class="form-control mb-3" name="email"><label class="form-label">Address</label><textarea class="form-control" name="address"></textarea></div><div class="modal-footer"><button class="btn btn-primary">Save Contact</button></div></form></div></div>`;document.body.insertAdjacentHTML('beforeend',html);const el=$('#partyModal');bootstrap.Modal.getOrCreateInstance(el).show();$('#partyForm').onsubmit=async e=>{e.preventDefault();try{await api('save_party',Object.fromEntries(new FormData(e.target)));bootstrap.Modal.getInstance(el).hide();el.remove();toast('Contact saved');parties()}catch(err){toast(err.message)}};el.addEventListener('hidden.bs.modal',()=>el.remove())}
async function movements(){const rows=await api('stock_movements',null,'GET');$('#content').innerHTML=`<div class="panel"><div class="panel-title">Inventory Audit Trail</div><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Product</th><th>Type</th><th>Quantity</th><th>Reference</th><th>Note</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.created_at)}</td><td>${esc(x.product_name)}</td><td><span class="badge ${x.movement_type==='IN'?'text-bg-success':'text-bg-danger'}">${x.movement_type}</span></td><td>${x.quantity} ${esc(x.unit)}</td><td>${esc(x.reference_no)}</td><td>${esc(x.note)}</td></tr>`).join('')}</tbody></table></div></div>`}
async function reports(){const d=await api('report',null,'GET');const rows=(arr)=>arr.length?arr.map(x=>`<tr><td>${esc(x.month)}</td><td class="text-end fw-semibold">${money(x.total)}</td></tr>`).join(''):'<tr><td colspan="2" class="empty">No data yet.</td></tr>';$('#content').innerHTML=`<div class="row g-3"><div class="col-lg-6"><div class="panel"><div class="panel-title">Monthly Sales</div><table class="table"><thead><tr><th>Month</th><th class="text-end">Sales</th></tr></thead><tbody>${rows(d.sales)}</tbody></table></div></div><div class="col-lg-6"><div class="panel"><div class="panel-title">Monthly Purchases</div><table class="table"><thead><tr><th>Month</th><th class="text-end">Purchase</th></tr></thead><tbody>${rows(d.purchases)}</tbody></table></div></div></div>`}
init();
</script>
</body></html>
